describe('Mobile Touch Target Size Test', () => {
  beforeEach(() => {
    cy.visit('/mobile-app');
  });

  it('should have large enough touch targets for easy tapping on mobile', () => {
    // Verify button has minimum touch target size
    cy.get('[data-testid="submit-button"]').should('be.visible');
    cy.get('[data-testid="submit-button"]').should('have.css', 'min-width', '48px');
    cy.get('[data-testid="submit-button"]').should('have.css', 'min-height', '48px');

    // Verify form input has minimum touch target size
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="email-input"]').should('have.css', 'min-width', '48px');
    cy.get('[data-testid="email-input"]').should('have.css', 'min-height', '48px');

    // Verify navigation links have minimum touch target size
    cy.get('[data-testid="nav-link-home"]').should('be.visible');
    cy.get('[data-testid="nav-link-home"]').should('have.css', 'min-width', '48px');
    cy.get('[data-testid="nav-link-home"]').should('have.css', 'min-height', '48px');

    // Verify list items have minimum touch target size
    cy.get('[data-testid="list-item-1"]').should('be.visible');
    cy.get('[data-testid="list-item-1"]').should('have.css', 'min-width', '48px');
    cy.get('[data-testid="list-item-1"]').should('have.css', 'min-height', '48px');

    // Verify error message has minimum touch target size
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('have.css', 'min-width', '48px');
    cy.get('[data-testid="error-message"]').should('have.css', 'min-height', '48px');
  });

  it('should handle edge case where touch targets are too small on mobile', () => {
    // Intercept API call to simulate small touch target
    cy.intercept('GET', '/api/data').as('getData');

    cy.get('[data-testid="small-touch-target"]').should('be.visible');

    // Verify touch target is too small
    cy.get('[data-testid="small-touch-target"]').should('have.css', 'min-width', '20px');
    cy.get('[data-testid="small-touch-target"]').should('have.css', 'min-height', '20px');

    // Attempt to interact with small touch target
    cy.get('[data-testid="small-touch-target"]').click();

    // Verify error is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Touch target too small');

    // Verify API call was made
    cy.wait('@getData').then((interception) => {
      expect(interception.response.statusCode).to.equal(500);
    });
  });
});
